func parseKey(seq []byte) keyEvent {
	if len(seq) == 0 {
		return keyEvent{kind: keyUnknown}
	}
	if len(seq) == 1 {
		switch seq[0] {
		case 0x03:
			return keyEvent{kind: keyCtrlC}
		case '\r', '\n':
			return keyEvent{kind: keyEnter}
		case 0x7f, 0x08:
			return keyEvent{kind: keyBackspace}
		case 0x1b:
			return keyEvent{kind: keyEsc}
		default:
			if seq[0] < utf8.RuneSelf {
				return keyEvent{kind: keyRune, r: rune(seq[0])}
			}
		}
	}

	s := string(seq)
	switch s {
	case "\x1b[A":
		return keyEvent{kind: keyUp}
	case "\x1b[B":
		return keyEvent{kind: keyDown}
	case "\x1b[C":
		return keyEvent{kind: keyRight}
	case "\x1b[D":
		return keyEvent{kind: keyLeft}
	case "\x1b[1;2A":
		return keyEvent{kind: keyShiftUp}
	case "\x1b[1;2B":
		return keyEvent{kind: keyShiftDown}
	case "\x1b[3~":
		return keyEvent{kind: keyDelete}
	}
	if strings.HasPrefix(s, "\x1b]") || strings.HasSuffix(s, "R") {
		return keyEvent{kind: keyUnknown}
	}
	if len(seq) == 1 {
		return keyEvent{kind: keyRune, r: rune(seq[0])}
	}
	r, _ := utf8.DecodeRune(seq)
	if r != utf8.RuneError {
		return keyEvent{kind: keyRune, r: r}
	}
	return keyEvent{kind: keyUnknown}
}

