func (a *app) handleRune(r rune) bool {
	switch r {
	case 'q':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.exit(true)
		return true
	case 'j':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.moveSelection(1)
	case 'k':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.moveSelection(-1)
	case 'h':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.goUp()
	case 'l':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.activateSelection()
	case '/':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.searchMode = true
		a.searchQuery = ""
	case 'd':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.armOrDelete()
	case 'u':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.undoDelete()
	case 'y':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.copySelection()
	case '.':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		oldIndex := a.selected
		a.cfg.hideHidden = !a.cfg.hideHidden
		a.reload(selectionSpec{mode: selectKeepIndex, index: oldIndex})
	case '?':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.showHelp = true
	case ' ':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.togglePreview()
	default:
		if a.searchMode {
			a.appendSearchRune(r)
		}
	}
	return false
}

func (a *app) handleSearchBackspace() {
	a.clearDeleteArm()
	if a.searchQuery == "" {
		a.searchMode = false
		return
	}
	runes := []rune(a.searchQuery)
	a.searchQuery = string(runes[:len(runes)-1])
	if a.searchQuery != "" {
		a.jumpToBestMatch()
	}
}

func (a *app) appendSearchRune(r rune) {
	a.clearDeleteArm()
	a.searchMode = true
	a.searchQuery += string(r)
	a.jumpToBestMatch()
}

func (a *app) moveSelection(delta int) {
	if len(a.entries) == 0 || a.selected < 0 {
		return
	}
	next := a.selected + delta
	if next < 0 {
		next = len(a.entries) - 1
	}
	if next >= len(a.entries) {
		next = 0
	}
	a.selected = next
	a.ensureVisible()
}

func (a *app) jumpSelection(index int) {
	if len(a.entries) == 0 {
		return
	}
	if index < 0 {
		index = 0
	}
	if index >= len(a.entries) {
		index = len(a.entries) - 1
	}
	a.selected = index
	a.ensureVisible()
}

func (a *app) jumpToBestMatch() {
	if a.searchQuery == "" || len(a.entries) == 0 {
		return
	}
	bestIndex := -1
	bestScore := math.MinInt
	for idx, item := range a.entries {
		score, ok := fuzzyScore(item.name, a.searchQuery)
		if !ok {
			continue
		}
		if score > bestScore || (score == bestScore && idx > bestIndex) {
			bestScore = score
			bestIndex = idx
		}
	}
	if bestIndex >= 0 {
		a.selected = bestIndex
		a.ensureVisible()
	}
}

func fuzzyScore(name, query string) (int, bool) {
	nameRunes := []rune(strings.ToLower(name))
	queryRunes := []rune(strings.ToLower(query))
	if len(queryRunes) == 0 {
		return 0, false
	}

	first, last := -1, -1
	pos := 0
	for _, q := range queryRunes {
		found := false
		for pos < len(nameRunes) {
			if nameRunes[pos] == q {
				if first == -1 {
					first = pos
				}
				last = pos
				pos++
				found = true
				break
			}
			pos++
		}
		if !found {
			return 0, false
		}
	}

	score := 1000 - (last - first)
	if strings.HasPrefix(strings.ToLower(name), strings.ToLower(query)) {
		score += 2000
	}
	if idx := strings.Index(strings.ToLower(name), strings.ToLower(query)); idx >= 0 {
		score += 1000 - idx
	}
	score -= len(nameRunes) - len(queryRunes)
	return score, true
}

func (a *app) currentEntry() *entry {
	if a.selected < 0 || a.selected >= len(a.entries) {
		return nil
	}
	return &a.entries[a.selected]
}

func (a *app) reload(spec selectionSpec) {
	dirEntries, err := os.ReadDir(a.currentPath)
	if err != nil {
		a.entries = nil
		a.currentError = err
		a.selected = -1
		a.scroll = 0
		return
	}

	items := make([]entry, 0, len(dirEntries))
	for _, de := range dirEntries {
		name := de.Name()
		if a.cfg.hideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if a.cfg.dirOnly && !de.IsDir() {
			continue
		}
		items = append(items, entry{
			name:     name,
			fullPath: filepath.Join(a.currentPath, name),
			dirEntry: de,
		})
	}

	sort.Slice(items, func(i, j int) bool {
		return items[i].name < items[j].name
	})

	a.entries = items
	a.currentError = nil

	if len(items) == 0 {
		a.selected = -1
		a.scroll = 0
		return
	}

	switch spec.mode {
	case selectKeepIndex:
		if spec.index < 0 {
			a.selected = 0
		} else if spec.index >= len(items) {
			a.selected = len(items) - 1
		} else {
			a.selected = spec.index
		}
	case selectByName:
		a.selected = 0
		for idx, item := range items {
			if item.name == spec.name {
				a.selected = idx
				break
			}
		}
	default:
		a.selected = 0
	}
	a.ensureVisible()
}

func (a *app) ensureVisible() {
	visibleRows := a.listRowsAvailable()
	if visibleRows <= 0 || a.selected < 0 {
		a.scroll = 0
		return
	}
	if a.selected < a.scroll {
		a.scroll = a.selected
	}
	if a.selected >= a.scroll+visibleRows {
		a.scroll = a.selected - visibleRows + 1
	}
	if a.scroll < 0 {
		a.scroll = 0
	}
}

func (a *app) activateSelection() {
	item := a.currentEntry()
	if item == nil {
		return
	}
	if item.IsDir() {
		a.currentPath = item.fullPath
		a.selected = -1
		a.scroll = 0
		a.reload(selectionSpec{mode: selectFirst})
		return
	}
	_ = a.openEntry(*item)
}

func (a *app) goUp() {
	parent := filepath.Dir(a.currentPath)
	if parent == a.currentPath {
		return
	}
	child := filepath.Base(a.currentPath)
	a.currentPath = parent
	a.reload(selectionSpec{mode: selectByName, name: child})
}

func (a *app) armOrDelete() {
	if a.currentEntry() == nil {
		return
	}
	if a.armedDelete == a.selected {
		a.performDelete()
		return
	}
	a.armedDelete = a.selected
}

func (a *app) clearDeleteArm() {
	a.armedDelete = -1
}

func (a *app) performDelete() {
	item := a.currentEntry()
	if item == nil {
		return
	}
	oldIndex := a.selected
	a.armedDelete = -1

	pending := &pendingDelete{
		name:         item.name,
		originalPath: item.fullPath,
		deadline:     time.Now().Add(deleteCountdown),
	}

	if strings.TrimSpace(a.removeCmd) != "" {
		_ = runShellCommand(a.removeCmd, item.fullPath, os.Stdin, os.Stdout, os.Stderr)
	} else {
		temporary, err := moveToTrash(item.fullPath)
		if err != nil {
			a.topMessage = err.Error()
			return
		}
		pending.temporary = temporary
		pending.canUndo = true
	}

	a.pending = pending
	a.reload(selectionSpec{mode: selectKeepIndex, index: oldIndex})
}

func moveToTrash(path string) (string, error) {
	base := filepath.Base(path)
	trashDir, err := os.MkdirTemp("", "walk-trash-")
	if err != nil {
		return "", err
	}
	target := filepath.Join(trashDir, base)
	if err := os.Rename(path, target); err != nil {
		_ = os.RemoveAll(trashDir)
		return "", err
	}
	return target, nil
}

func (a *app) undoDelete() {
	if a.pending == nil {
		return
	}
	defer func() {
		if !a.pending.canUndo {
			a.pending = nil
		}
	}()

	if !a.pending.canUndo || a.pending.temporary == "" {
		return
	}
	if err := os.Rename(a.pending.temporary, a.pending.originalPath); err != nil {
		return
	}
	_ = os.Remove(filepath.Dir(a.pending.temporary))
	restoredDir := filepath.Dir(a.pending.originalPath)
	name := filepath.Base(a.pending.originalPath)
	a.pending = nil
	if a.currentPath == restoredDir {
		a.reload(selectionSpec{mode: selectByName, name: name})
	}
}

func (a *app) tick(now time.Time) bool {
	if a.pending == nil {
		return false
	}
	if now.Before(a.pending.deadline) {
		return true
	}
	if a.pending.canUndo && a.pending.temporary != "" {
		_ = os.RemoveAll(filepath.Dir(a.pending.temporary))
	}
	a.pending = nil
	return true
}

func (a *app) copySelection() {
	item := a.currentEntry()
	if item == nil {
		return
	}
	_ = copyToClipboard(item.fullPath)
	a.topMessage = "copied: " + item.fullPath
}
